                         *      Decode EVERYTHING as a TLV.
                         */
                        while (p < end) {
                                slen = decode_tlv(child_ctx, &child_cursor, fr_dict_by_da(child), child, p, end - p, decode_ctx);
                                if (slen < 0) {
